```js
function valueNoise(size, freq, seed) {
  var rnd = mulberry32(seed >>> 0 || 1);
  var n = Math.max(2, Math.min(size, freq | 0));
  var grid = new Float32Array(n * n);
  for (var i = 0; i < n * n; i++) grid[i] = rnd();
  var out = new Float32Array(size * size);
  var scale = n / size;
  for (var y = 0; y < size; y++) {
    var fy = y * scale, y0 = Math.floor(fy), ty = fy - y0, y1 = (y0 + 1) % n; y0 %= n;
    var sy = ty * ty * (3 - 2 * ty);
    for (var x = 0; x < size; x++) {
      var fx = x * scale, x0 = Math.floor(fx), tx = fx - x0, x1 = (x0 + 1) % n; x0 %= n;
      var sx = tx * tx * (3 - 2 * tx);
      var a = grid[y0*n+x0], b = grid[y0*n+x1], c2 = grid[y1*n+x0], d = grid[y1*n+x1];
      out[y*size+x] = (a + (b-a)*sx) * (1-sy) + (c2 + (d-c2)*sx) * sy;
    }
  }
  return out;
}
```
Tileable because lattice wraps modulo n and freq lattice spans full size. Yes tileable.

