function fbm(size, opts) {
  opts = opts || {};
  var f = opts.freq || 4, oct = opts.octaves || 4, gain = opts.gain === undefined ? 0.5 : opts.gain;
  var seed = opts.seed || 1, ridged = !!opts.ridged;
  var out = new Float32Array(size*size), amp = 1, total = 0;
  for (var o = 0; o < oct; o++) {
    var n = valueNoise(size, f, seed + o * 1013);
    for (var i = 0; i < out.length; i++) {
      var v = n[i];
      if (ridged) v = 1 - Math.abs(v * 2 - 1);
      out[i] += v * amp;
    }
    total += amp; amp *= gain; f *= 2;
  }
  for (var j = 0; j < out.length; j++) out[j] /= total;
  return out;
}
```
