// overlays a 0..1 height field on the canvas pixels (signed brightness shift)
function applyField(ctx, size, field, opts) {
  opts = opts || {};
  var amt = opts.amount == null ? 0.2 : opts.amount;
  var contrast = opts.contrast == null ? 0 : opts.contrast;
  var img = ctx.getImageData(0, 0, size, size), d = img.data;
  for (var i = 0, p = 0; i < field.length; i++, p += 4) {
    var v = (field[i] - 0.5) * 2;                 // -1..1
    if (contrast) v = v < 0 ? v * (1 - contrast) : v * (1 + contrast);
    var k = 1 + v * amt;
    d[p] = d[p] * k; d[p + 1] = d[p + 1] * k; d[p + 2] = d[p + 2] * k;
