// Sobel-derived tangent-space normal map from the luminance of a source canvas
function normalMapFromHeight(canvas, strength) {
  var size = canvas.width;
  var src = canvas.getContext('2d').getImageData(0, 0, size, size).data;
  var h = new Float32Array(size * size);
  for (var i = 0, p = 0; i < h.length; i++, p += 4) {
    h[i] = (src[p] * 0.299 + src[p + 1] * 0.587 + src[p + 2] * 0.114) / 255;
  }
  var s = (strength || 3) * 0.25;
  var out = makeCanvas(size), img = out.ctx.createImageData(size, size), d = img.data;
  for (var y = 0; y < size; y++) {
    var ym = ((y - 1 + size) % size) * size, yp = ((y + 1) % size) * size, yc = y * size;
    for (var x = 0; x < size; x++) {
      var xm = (x - 1 + size) % size, xp = (x + 1) % size;
      var gx = (h[ym + xp] + 2 * h[yc + xp] + h[yp + xp]) - (h[ym + xm] + 2 * h[yc + xm] + h[yp + xm]);
      var gy = (h[yp + xm] + 2 * h[yp + x] + h[yp + xp]) - (h[ym + xm] + 2 * h[ym + x] + h[ym + xp]);
      var nx = -gx * s, ny = -gy * s, nz = 1;
      var inv = 1 / Math.sqrt(nx * nx + ny * ny + 1);
      var q = (y * size + x) * 4;
      d[q] = (nx * inv * 0.5 + 0.5) * 255;
      d[q + 1] = (ny * inv * 0.5 + 0.5) * 255;
      d[q + 2] = (nz * inv * 0.5 + 0.5) * 255;
      d[q + 3] = 255;
    }
  }
  out.ctx.putImageData(img, 0, 0);
  return texture(out.canvas, false);
}
```
