  /* -------------------------------------------------------------- noise */
  // Tileable value noise, returns a Float32Array of size*size values in 0..1
  function valueNoise(size, freq, seed) {
    var rnd = mulberry32(hash('vn' + (seed || 1)));
    var n = clamp(Math.round(freq || 4), 2, size);
    var grid = new Float32Array(n * n);
    for (var i = 0; i < grid.length; i++) grid[i] = rnd();
    var out = new Float32Array(size * size), scale = n / size;
    for (var y = 0; y < size; y++) {
      var fy = y * scale, y0 = fy | 0, ty = fy - y0, y1 = (y0 + 1) % n; y0 %= n;
      var sy = ty * ty * (3 - 2 * ty);
      for (var x = 0; x < size; x++) {
        var fx = x * scale, x0 = fx | 0, tx = fx - x0, x1 = (x0 + 1) % n; x0 %= n;
        var sx = tx * tx * (3 - 2 * tx);
        var top = grid[y0 * n + x0] + (grid[y0 * n + x1] - grid[y0 * n + x0]) * sx;
        var bot = grid[y1 * n + x0] + (grid[y1 * n + x1] - grid[y1 * n + x0]) * sx;
        out[y * size + x] = top + (bot - top) * sy;
      }
    }
    return out;
  }
```
