  // calls fn once per wrap copy needed for a shape of radius r at (x, y)
  function wrap(ctx, size, x, y, r, fn) {
    var xs = [0], ys = [0];
    if (x < r) xs.push(size); else if (x > size - r) xs.push(-size);
    if (y < r) ys.push(size); else if (y > size - r) ys.push(-size);
    for (var i = 0; i < xs.length; i++) for (var j = 0; j < ys.length; j++) {
      if (!xs[i] && !ys[j]) { fn(); continue; }
      ctx.save(); ctx.translate(xs[i], ys[j]); fn(); ctx.restore();
    }
  }
