    for (var i = 0; i < 5; i++) {
      var ox = (rnd() - 0.5) * r * jitter, oy = (rnd() - 0.5) * r * jitter;
      var rr = r * (0.62 + rnd() * 0.45);
      var g = ctx.createRadialGradient(x + ox, y + oy, 0, x + ox, y + oy, rr);
      g.addColorStop(0, 'rgba(' + rgb + ',' + alpha + ')');
      g.addColorStop(0.7, 'rgba(' + rgb + ',' + (alpha * 0.5) + ')');
      g.addColorStop(1, 'rgba(' + rgb + ',0)');
      ctx.fillStyle = g;
      ctx.beginPath(); ctx.arc(x + ox, y + oy, rr, 0, TAU); ctx.fill();
    }
  }
