  // cracked surface: jagged polylines plus short branches
  function cracks(ctx, size, opts) {
    opts = opts || {};
    var rnd = mulberry32(hash('ck' + (opts.seed || 1)));
    var count = opts.count || 6, color = opts.color || '26,25,24';
    var alpha = opts.alpha == null ? 0.55 : opts.alpha, width = opts.width || 1.5;
    var len = opts.len || size * 0.5, branch = opts.branch || 2;
    for (var i = 0; i < count; i++) {
      var pts = crackPath(rnd, rnd() * size, rnd() * size, rnd() * TAU, len, 8 + (rnd() * 6 | 0));
      strokeWrapped(ctx, size, pts, 'rgb(' + color + ')', width * (0.7 + rnd() * 0.7), alpha * (0.6 + rnd() * 0.5));
      for (var b = 0; b < branch; b++) {
        var at = 1 + (rnd() * (pts.length - 2) | 0);
        var a2 = Math.atan2(pts[at][1] - pts[at - 1][1], pts[at][0] - pts[at - 1][0]) + (rnd() < 0.5 ? -1 : 1) * (0.7 + rnd() * 0.6);
        strokeWrapped(ctx, size, crackPath(rnd, pts[at][0], pts[at][1], a2, len * 0.35, 5), 'rgb(' + color + ')', width * 0.7, alpha * 0.7);
      }
    }
  }

  function crackPath(rnd, x, y, ang, len, segs) {
    var pts = [[x, y]], step = len / segs;
    for (var i = 0; i < segs; i++) {
      ang += (rnd() - 0.5) * 0.9;
      x += Math.cos(ang) * step; y += Math.sin(ang) * step;
      pts.push([x, y]);
    }
    return pts;
  }
