  function paintWood(ctx, size, seed, planks, horizontal) {
    var rnd = mulberry32(hash('wd' + seed));
    planks = planks || 5;
    ctx.fillStyle = PAL.woodDark;
    ctx.fillRect(0, 0, size, size);
    ctx.save();
    if (horizontal) { ctx.translate(size / 2, size / 2); ctx.rotate(Math.PI / 2); ctx.translate(-size / 2, -size / 2); }
    var pw = size / planks;
    for (var p = 0; p < planks; p++) {
      var x0 = p * pw;
      ctx.fillStyle = shade(PAL.wood, (rnd() - 0.45) * 0.3);
      ctx.fillRect(x0 + 1.5, 0, pw - 3, size);
      for (var g = 0; g < 22; g++) {            // grain
        var gx = x0 + 2 + rnd() * (pw - 5);
        wavy(ctx, size, gx, 1 + rnd() * 3, 1 + (rnd() * 2 | 0), rnd() * TAU,
          rnd() < 0.5 ? 'rgb(58,44,29)' : 'rgb(150,126,96)', 0.5 + rnd() * 1.4, 0.16 + rnd() * 0.22);
      }
      if (rnd() < 0.65) {                        // knot
        var kx = x0 + pw * (0.3 + rnd() * 0.4), ky = rnd() * size, kr = 3 + rnd() * 5;
        for (var k = 4; k >= 0; k--) {
          ctx.strokeStyle = k % 2 ? 'rgba(48,35,22,0.5)' : 'rgba(122,100,74,0.35)';
          ctx.lineWidth = 1;
          ctx.beginPath(); ctx.arc(kx, ky, kr * (0.35 + k * 0.30), 0, TAU); ctx.stroke();
        }
      }
      for (var n = 0; n < 2; n++) {              // nail holes
        var nx = x0 + pw * (0.25 + n * 0.5), ny = size * (0.12 + rnd() * 0.76);
        ctx.fillStyle = 'rgba(30,24,18,0.8)';
        ctx.beginPath(); ctx.arc(nx, ny, 2.2, 0, TAU); ctx.fill();
        ctx.fillStyle = 'rgba(160,140,110,0.25)';
        ctx.beginPath(); ctx.arc(nx - 0.8, ny - 0.8, 1, 0, TAU); ctx.fill();
      }
    }
    ctx.restore();
    ctx.globalAlpha = 1;
    applyField(ctx, size, fbm(size, { freq: 4, octaves: 4, seed: seed + 7 }), { amount: 0.14 });
    grain(ctx, size, 0.045, seed + 9);
    return rnd;
  }
