  // soft irregular elliptical patch (rotated), rgb triplet + alpha
  function softEllipse(ctx, x, y, rx, ry, rot, rgb, alpha) {
    ctx.save();
    ctx.translate(x, y); ctx.rotate(rot); ctx.scale(1, Math.max(0.2, ry / rx));
    var g = ctx.createRadialGradient(0, 0, 0, 0, 0, rx);
    g.addColorStop(0, 'rgba(' + rgb + ',' + alpha + ')');
    g.addColorStop(0.75, 'rgba(' + rgb + ',' + alpha * 0.55 + ')');
    g.addColorStop(1, 'rgba(' + rgb + ',0)');
    ctx.fillStyle = g;
    ctx.beginPath(); ctx.arc(0, 0, rx, 0, TAU); ctx.fill();
    ctx.restore();
  }
